command:example.dev:code:
PS C:\> try {
    Get-odscTargetUser -CsvPath ".\users.csv" | Invoke-odscShortcutAssignment -Uri "https://contoso.sharepoint.com/sites/WorkingSite" -DocumentLibrary "Working Document Library" -ReportPath ".\report.csv" -StopOnError
} catch {
    Write-Warning $_.Exception.Message
}

PS C:\> try {
    New-odsc -Uri "https://contoso.sharepoint.com/sites/WorkingSite" -DocumentLibrary "Working Document Library" -UserPrincipalName "user@contoso.com" -ErrorAction Stop
} catch {
    Write-Warning "Shortcut not created: $($_.Exception.Message)"
    exit 1
}
